def minPath(grid, k):
    if k <= 0:
        return []
    n = len(grid)
    r, c = 0, 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j
    path = [grid[r][c]]
    for _ in range(k - 1):
        nbrs = [
            (r + dr, c + dc)
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))
            if 0 <= r + dr < n and 0 <= c + dc < n
        ]
        if nbrs:
            r, c = min(nbrs, key=lambda p: grid[p[0]][p[1]])
        path.append(grid[r][c])
    return path

def minPath(grid, k):
    if k <= 0 or not grid:
        return []

    n = len(grid)
    start_val = min(min(row) for row in grid)
    frontier = {(i, j) for i in range(n) for j in range(n) if grid[i][j] == start_val}
    path = [start_val]

    for _ in range(k - 1):
        best = None
        nxt = set()
        for i, j in frontier:
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    v = grid[ni][nj]
                    if best is None or v < best:
                        best = v
                        nxt = {(ni, nj)}
                    elif v == best:
                        nxt.add((ni, nj))
        if best is None:
            raise ValueError("no path of the requested length exists")
        path.append(best)
        frontier = nxt

    return path

