def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    if k <= 0 or n == 0:
        return []

    # The lexicographically smallest sequence must start with the smallest value.
    start_val = min(min(row) for row in grid)
    positions = {(r, c) for r in range(n) for c in range(n) if grid[r][c] == start_val}
    result = [start_val]

    for _ in range(1, k):
        # Gather all cells reachable in one move from the current frontier.
        candidates = set()
        for r, c in positions:
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    candidates.add((nr, nc))

        # Keep only the candidates holding the smallest next value.
        best = min(grid[r][c] for r, c in candidates)
        positions = {(r, c) for r, c in candidates if grid[r][c] == best}
        result.append(best)

    return result

