    n = len(grid)
    if k <= 0 or n == 0:
        return []

    def neighbors(r, c):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                yield nr, nc

    # Start with every cell, keep only those holding the smallest value.
    all_cells = [(r, c) for r in range(n) for c in range(n)]
    first = min(grid[r][c] for r, c in all_cells)
    frontier = {(r, c) for r, c in all_cells if grid[r][c] == first}
