    # reachable value from the current frontier.
    for _ in range(k - 1):
        candidates = set()
        for r, c in frontier:
            for nb in neighbors(r, c):
                candidates.add(nb)
        best = min(grid[r][c] for r, c in candidates)
        result.append(best)
        frontier = {(r, c) for r, c in candidates if grid[r][c] == best}

    return result

