def normalize_phone(s):
    if not isinstance(s, str):
        raise ValueError("Phone number must be a string")

    text = s.strip()

    # Only digits, spaces, dashes, dots, parentheses, and a leading '+' are allowed.
    if not re.fullmatch(r"[\d\s().\-+]+", text):
        raise ValueError(f"Invalid characters in phone number: {s!r}")

    # At most one '+', and it must be at the start.
    if text.count("+") > 1 or ("+" in text and not text.startswith("+")):
        raise ValueError(f"Invalid '+' placement in phone number: {s!r}")

    # Parentheses must be balanced and appear at most once each.
    if text.count("(") != text.count(")") or text.count("(") > 1:
        raise ValueError(f"Unbalanced parentheses in phone number: {s!r}")

    digits = re.sub(r"\D", "", text)

    if text.startswith("+"):
        # An explicit '+' must be followed by the US country code 1.
        if len(digits) != 11 or not digits.startswith("1"):
            raise ValueError(f"Invalid international phone number: {s!r}")
        digits = digits[1:]
    elif len(digits) == 11 and digits.startswith("1"):
        # Country code without the '+'.
        digits = digits[1:]

    if len(digits) != 10:
        raise ValueError(f"US phone number must have 10 digits: {s!r}")

    # NANP rules: area code and exchange must start with a digit from 2-9.
    if digits[0] in "01":
        raise ValueError(f"Invalid area code in phone number: {s!r}")
    if digits[3] in "01":
        raise ValueError(f"Invalid exchange code in phone number: {s!r}")

    return f"({digits[:3]}) {digits[3:6]}-{digits[6:]}"

