def parse_kv(line):
    def split_fields(s):
        fields, buf, in_q, i = [], [], False, 0
        while i < len(s):
            c = s[i]
            if in_q and c == '\\' and i + 1 < len(s):
                buf.append(c)
                buf.append(s[i + 1])
                i += 2
                continue
            if c == '"':
                in_q = not in_q
            if c == ';' and not in_q:
                fields.append(''.join(buf))
                buf = []
            else:
                buf.append(c)
            i += 1
        if in_q:
            raise ValueError("unterminated quoted value")
        fields.append(''.join(buf))
        return fields

    def find_unquoted_eq(s):
        in_q, i = False, 0
        while i < len(s):
            c = s[i]
            if in_q and c == '\\' and i + 1 < len(s):
                i += 2
                continue
            if c == '"':
                in_q = not in_q
            elif c == '=' and not in_q:
                return i
            i += 1
        return -1

    def unquote(v):
        if len(v) >= 2 and v[0] == '"' and v[-1] == '"':
            inner = v[1:-1]
            out, i = [], 0
            while i < len(inner):
                if inner[i] == '\\' and i + 1 < len(inner):
                    out.append(inner[i + 1])
                    i += 2
                else:
                    out.append(inner[i])
                    i += 1
            return ''.join(out)
        return v

    result = {}
    for field in split_fields(line):
        field = field.strip()
        if not field:
            continue
        eq = find_unquoted_eq(field)
        if eq == -1:
            result[field] = True
        else:
            key = field[:eq].strip()
            value = field[eq + 1:].strip()
            result[key] = unquote(value)
    return result

def parse_kv(line):
    """Parse a config line like 'a=1; debug; msg="hi; there"' into a dict.

    - Pairs are separated by semicolons. Semicolons inside double-quoted
      values do not split pairs.
    - 'key=value' maps to the string value.
    - A bare key (no '=') maps to True.
    - Double-quoted values have their quotes removed. Inside quotes, a
      backslash escapes the following character (e.g. \\" or \\\\).
    - Raises ValueError if a double quote is never closed.
    """
    segments = []
    current = []
    in_quotes = False
    escape = False

    for ch in line:
        if escape:
            current.append(ch)
            escape = False
        elif in_quotes and ch == "\\":
            current.append(ch)
            escape = True
        elif ch == '"':
            current.append(ch)
            in_quotes = not in_quotes
        elif ch == ";" and not in_quotes:
            segments.append("".join(current))
            current = []
        else:
            current.append(ch)

    if in_quotes:
        raise ValueError("unterminated quoted value in config line")

    segments.append("".join(current))

    result = {}
    for segment in segments:
        segment = segment.strip()
        if not segment:
            continue

        key, sep, value = segment.partition("=")
        key = key.strip()
        if not sep:
            result[key] = True
