            return value
        if kind is None:
            raise SyntaxError("unexpected end of expression")
        raise SyntaxError(f"unexpected token {kind!r}")

    def expect_end(self):
        if self.pos != len(self.tokens):
            raise SyntaxError(f"unexpected token {self.tokens[self.pos][0]!r}")


