import io


def column_stats(csv_text, column):
    reader = csv.reader(io.StringIO(csv_text))

    # Find the header row, skipping any leading blank lines.
    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = [name.strip() for name in row]
            break

    if header is None or column not in header:
        raise KeyError(f"Column not found: {column!r}")

    index = header.index(column)

    values = []
    for row in reader:
        if index >= len(row):
            continue
        cell = row[index].strip()
        if cell == "":
            continue
        try:
            value = int(cell)
        except ValueError:
            value = float(cell)
        values.append(value)

    count = len(values)
    if count == 0:
        return {"count": 0, "sum": 0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
