def evaluate(expr):
    """
    Evaluate an integer arithmetic expression.

    Supports integer literals, + - * / % ^, unary minus, and parentheses.
    Division and modulo truncate toward zero (C-style), so the remainder
    takes the sign of the dividend. '^' is right-associative and binds
    tighter than unary minus, so -2^2 == -4.

    Raises SyntaxError for malformed input and ZeroDivisionError for
    division or modulo by zero.
    """

    # ---------- Tokenizer ----------
    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
            elif '0' <= c <= '9':
                start = i
                while i < n and '0' <= s[i] <= '9':
                    i += 1
                tokens.append(('NUM', int(s[start:i])))
            elif c in '+-*/%^':
                tokens.append(('OP', c))
                i += 1
            elif c == '(':
                tokens.append(('LPAREN', c))
                i += 1
            elif c == ')':
                tokens.append(('RPAREN', c))
                i += 1
            else:
                raise SyntaxError(f"Unexpected character {c!r} at position {i}")
        tokens.append(('END', None))
        return tokens

    # ---------- Integer arithmetic helpers ----------
    def c_div(a, b):
        if b == 0:
            raise ZeroDivisionError("division by zero")
        q = abs(a) // abs(b)
        return q if (a >= 0) == (b >= 0) else -q

    def c_mod(a, b):
        if b == 0:
            raise ZeroDivisionError("modulo by zero")
        return a - b * c_div(a, b)

    def c_pow(base, exp):
        if exp >= 0:
            return base ** exp
        # Negative exponent: only well-defined integers for these bases.
        if base == 1:
            return 1
        if base == -1:
            return 1 if exp % 2 == 0 else -1
        if base == 0:
            raise ZeroDivisionError("zero raised to a negative power")
        raise ValueError("negative exponent yields a non-integer result")

    # ---------- Recursive-descent parser ----------
    tokens = tokenize(expr)
    pos = 0

    def peek():
        return tokens[pos]

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def expect_end():
        if peek()[0] != 'END':
            raise SyntaxError(f"Unexpected token {peek()[1]!r}")

    # expr := term (('+' | '-') term)*
    def parse_expr():
        value = parse_term()
        while peek()[0] == 'OP' and peek()[1] in '+-':
            op = advance()[1]
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    # term := unary (('*' | '/' | '%') unary)*
    def parse_term():
        value = parse_unary()
        while peek()[0] == 'OP' and peek()[1] in '*/%':
            op = advance()[1]
            rhs = parse_unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = c_div(value, rhs)
            else:
                value = c_mod(value, rhs)
        return value

    # unary := '-' unary | power
    def parse_unary():
        if peek()[0] == 'OP' and peek()[1] == '-':
            advance()
            return -parse_unary()
        return parse_power()

    # power := atom ['^' unary]   (right-associative; exponent may be negated)
    def parse_power():
        base = parse_atom()
        if peek()[0] == 'OP' and peek()[1] == '^':
            advance()
            exp = parse_unary()
            return c_pow(base, exp)
        return base

    # atom := NUMBER | '(' expr ')'
    def parse_atom():
        kind, val = peek()
        if kind == 'NUM':
            advance()
            return val
        if kind == 'LPAREN':
            advance()
            value = parse_expr()
            if peek()[0] != 'RPAREN':
                raise SyntaxError("Expected ')'")
            advance()
            return value
        if kind == 'END':
            raise SyntaxError("Unexpected end of expression")
        raise SyntaxError(f"Unexpected token {val!r}")

    if tokens[0][0] == 'END':
        raise SyntaxError("Empty expression")

    result = parse_expr()
    expect_end()
    return result

from typing import Dict, List, Optional, Union

ACCEPTED_COINS = (5, 10, 25)


class VendingMachine:
    def __init__(self, prices: Dict[str, int], coins: Dict[int, int]):
        self.prices: Dict[str, int] = dict(prices)
        self.coins: Dict[int, int] = {d: c for d, c in coins.items() if c > 0}
        self.inserted: List[int] = []

    def insert(self, coin: int) -> bool:
        if coin not in ACCEPTED_COINS:
            return False
        self.inserted.append(coin)
        return True

    def balance(self) -> int:
        return sum(self.inserted)

    def select(self, item: str) -> Union[List[int], str]:
        if item not in self.prices:
            return 'UNKNOWN'

        price = self.prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'

        # Inserted coins become part of the pool available for change.
        pool: Dict[int, int] = dict(self.coins)
        for coin in self.inserted:
            pool[coin] = pool.get(coin, 0) + 1

        change = self._make_change(bal - price, pool)
        if change is None:
            return 'NO_CHANGE'

        for coin in change:
            pool[coin] -= 1
        self.coins = {d: c for d, c in pool.items() if c > 0}
        self.inserted = []
        return change

    def cancel(self) -> List[int]:
        returned = list(self.inserted)
        self.inserted = []
        return returned

    @staticmethod
    def _make_change(amount: int, pool: Dict[int, int]) -> Optional[List[int]]:
        """Return the fewest coins from pool summing to amount, or None if impossible."""
        if amount == 0:
            return []

        denoms = sorted(d for d, c in pool.items() if c > 0 and d > 0)
        INF = float('inf')
        best = [INF] * (amount + 1)
        best[0] = 0
        picks: List[List[int]] = []

        # Bounded knapsack over denominations: best[a] = min coins to make a.
        for d in denoms:
            count = pool[d]
            new_best = [INF] * (amount + 1)
            pick = [0] * (amount + 1)
            for a in range(amount + 1):
                for j in range(min(count, a // d) + 1):
                    candidate = best[a - j * d] + j
                    if candidate < new_best[a]:
                        new_best[a] = candidate
                        pick[a] = j
            picks.append(pick)
            best = new_best

        if best[amount] == INF:
            return None

        # Reconstruct the chosen coins by walking the stages backwards.
        result: List[int] = []
        a = amount
        for idx in range(len(denoms) - 1, -1, -1):
            d = denoms[idx]
            j = picks[idx][a]
            result.extend([d] * j)
            a -= j * d

        return sorted(result, reverse=True)

