class Scheduler:
    """Books a single room using half-open intervals [start, end)."""

    def __init__(self):
        # Parallel lists of non-overlapping bookings, sorted by start.
        # Because bookings never overlap, ends are sorted too.
        self._starts = []
        self._ends = []

    @staticmethod
    def _validate(start, end):
        if start >= end:
            raise ValueError(f"invalid interval [{start}, {end}): start must be less than end")

    def book(self, start, end):
        """Book [start, end). Returns False if it overlaps an existing booking."""
        self._validate(start, end)
        i = bisect.bisect_left(self._starts, start)
        # Previous booking overlaps if it ends after our start.
        if i > 0 and self._ends[i - 1] > start:
            return False
        # Next booking overlaps if it starts before our end.
        if i < len(self._starts) and self._starts[i] < end:
            return False
        self._starts.insert(i, start)
        self._ends.insert(i, end)
        return True

    def cancel(self, start, end):
        """Remove the booking exactly matching [start, end). Returns True if removed."""
        self._validate(start, end)
        i = bisect.bisect_left(self._starts, start)
        if i < len(self._starts) and self._starts[i] == start and self._ends[i] == end:
            del self._starts[i]
            del self._ends[i]
            return True
        return False

    def bookings(self):
        """Return all bookings as a sorted list of (start, end) tuples."""
        return list(zip(self._starts, self._ends))

    def free_slots(self, lo, hi, min_len=1):
        """Return free gaps (start, end) inside the window [lo, hi) whose
        length is at least min_len, sorted by start."""
        if lo >= hi:
            return []
        slots = []
        cur = lo
        # First booking that ends after lo (may start before lo).
        i = bisect.bisect_right(self._ends, lo)
        while i < len(self._starts) and self._starts[i] < hi:
            s, e = self._starts[i], self._ends[i]
            if s > cur:
                gap_end = min(s, hi)
                if gap_end - cur >= min_len and gap_end > cur:
                    slots.append((cur, gap_end))
            cur = max(cur, e)
            i += 1
        if cur < hi and hi - cur >= min_len:
            slots.append((cur, hi))
        return slots

