        if i > 0 and self._intervals[i - 1][1] > start:
            return False
        # Next booking overlaps if it starts before our end.
        if i < len(self._intervals) and self._intervals[i][0] < end:
            return False
        self._intervals.insert(i, (start, end))
        return True

