        """Cancel the booking exactly matching [start, end).

        Return True if it was found and removed, False otherwise.
        """
        i = bisect_left(self._intervals, (start, end))
        if i < len(self._intervals) and self._intervals[i] == (start, end):
            del self._intervals[i]
            return True
        return False

