        cursor = lo
        for s, e in self._intervals:
            if e <= lo:
                continue
            if s >= hi:
                break
            if s > cursor:
                gaps.append((cursor, s))
            if e > cursor:
                cursor = e
        if cursor < hi:
            gaps.append((cursor, hi))

        return [(a, b) for a, b in gaps if b - a >= min_len]

