def color_graph(nodes, edges, k, precolored=None):
    adj = {n: set() for n in nodes}
    for u, v in edges:
        if u == v:
            return None  # a self-loop can never be properly colored
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)

    if k <= 0:
        return {} if not adj else None

    colors = {}
    if precolored:
        for n, c in precolored.items():
            if not isinstance(c, int) or c < 0 or c >= k:
                return None
            adj.setdefault(n, set())
            colors[n] = c
        for n, c in colors.items():
            for m in adj[n]:
                if colors.get(m) == c:
                    return None

    domains = {}
    for n in adj:
        if n in colors:
            continue
        forbidden = {colors[m] for m in adj[n] if m in colors}
        domains[n] = set(range(k)) - forbidden
        if not domains[n]:
            return None

    def search(colors, domains):
        if len(colors) == len(adj):
            return True
        # Most-constrained variable first, ties broken by highest degree.
        n = min(domains, key=lambda x: (len(domains[x]), -len(adj[x])))
        if not domains[n]:
            return False
        for c in sorted(domains[n]):
            new_domains = {x: set(d) for x, d in domains.items() if x != n}
            ok = True
            for m in adj[n]:
                if m in new_domains:
                    new_domains[m].discard(c)
                    if not new_domains[m]:
                        ok = False
                        break
            if not ok:
                continue
            colors[n] = c
            if search(colors, new_domains):
                return True
            del colors[n]
        return False

    if search(colors, domains):
        return dict(colors)
    return None

