    if not adj:
        return {}
    if k <= 0:
        return None

    # Precolored neighbors must not share a color.
    for v, c in precolored.items():
        for u in adj[v]:
            if u in precolored and precolored[u] == c:
                return None

    domains = {}
    for v in adj:
        if v in precolored:
            domains[v] = {precolored[v]}
        else:
            domains[v] = set(range(k))

    def search(assignment, domains):
        if len(assignment) == len(adj):
            return assignment

        # Minimum-remaining-values choice, ties broken by highest degree.
        v = min(
            (x for x in adj if x not in assignment),
            key=lambda x: (len(domains[x]), -len(adj[x])),
        )

        for c in sorted(domains[v]):
            new_assignment = dict(assignment)
