    for u, v in edges:
        if u == v:
            return None  # self-loop: a node cannot differ from itself
        add_node(u)
        add_node(v)
        adj[u].add(v)
        adj[v].add(u)

    for n in precolored:
        add_node(n)

    if not all_nodes:
        return {}
    if not isinstance(k, int) or k <= 0:
        return None

