def color_graph(nodes, edges, k, precolored=None):
    adj = defaultdict(set)
    all_nodes = list(dict.fromkeys(nodes))
    node_set = set(all_nodes)

    for u, v in edges:
        if u == v:
            return None  # a self-loop can never be properly colored
        adj[u].add(v)
        adj[v].add(u)
        for x in (u, v):
            if x not in node_set:
                node_set.add(x)
                all_nodes.append(x)

    precolored = dict(precolored or {})
    for n in precolored:
        if n not in node_set:
            node_set.add(n)
            all_nodes.append(n)

    if not all_nodes:
        return {}
    if k <= 0:
        return None

    for c in precolored.values():
        if not isinstance(c, int) or c < 0 or c >= k:
            return None

    # Precolored nodes must not conflict with each other.
    for n, c in precolored.items():
        for m in adj[n]:
            if m in precolored and precolored[m] == c:
                return None

    colors = dict(precolored)
    remaining = {n for n in all_nodes if n not in colors}

    def solve():
        if not remaining:
            return True

        # Choose the uncolored node with the fewest legal colors (most constrained first).
        best = None
        best_opts = None
        for n in remaining:
            used = {colors[m] for m in adj[n] if m in colors}
            opts = [c for c in range(k) if c not in used]
            if best_opts is None or len(opts) < len(best_opts):
                best, best_opts = n, opts
                if len(opts) <= 1:
                    break

        if not best_opts:
            return False

        remaining.remove(best)
        for c in best_opts:
            colors[best] = c
            if solve():
                return True
            del colors[best]
        remaining.add(best)
        return False

    if solve():
        return dict(colors)
    return None

from collections import defaultdict


def color_graph(nodes, edges, k, precolored=None):
    """
    Return a dict mapping every node to a color in 0..k-1 such that adjacent
    nodes receive different colors, keeping any precolored nodes fixed.
    Return None if no such coloring exists.
    """
    adj = defaultdict(set)
    all_nodes = set(nodes)

    for u, v in edges:
        all_nodes.add(u)
        all_nodes.add(v)
        if u == v:
            return None  # a self-loop can never be properly colored
        adj[u].add(v)
        adj[v].add(u)

    fixed = dict(precolored or {})
    for n in fixed:
        all_nodes.add(n)

    if not all_nodes:
        return {}
    if k <= 0:
        return None

    for n, c in fixed.items():
        if not isinstance(c, int) or c < 0 or c >= k:
            return None
    for n, c in fixed.items():
        for m in adj[n]:
            if m in fixed and fixed[m] == c:
                return None

    colors = {}
    domains = {n: set(range(k)) for n in all_nodes}

    def assign(n, c, removed):
        """Fix n to color c and prune c from uncolored neighbors' domains.
        Records pruned (node, color) pairs in `removed`. Returns False if
        some uncolored neighbor's domain becomes empty."""
        colors[n] = c
        ok = True
        for m in adj[n]:
            if m not in colors and c in domains[m]:
                domains[m].discard(c)
                removed.append((m, c))
                if not domains[m]:
                    ok = False
        return ok

    def unassign(n, removed):
        del colors[n]
        for m, c in removed:
            domains[m].add(c)

    # Apply precolored nodes first (propagating their constraints).
    for n, c in fixed.items():
        removed = []
        if not assign(n, c, removed):
            return None

    def search():
        uncolored = [n for n in all_nodes if n not in colors]
        if not uncolored:
            return True
        # Most constrained variable first; break ties by highest degree.
        n = min(uncolored, key=lambda x: (len(domains[x]), -len(adj[x]), str(x)))
        for c in sorted(domains[n]):
            removed = []
            if assign(n, c, removed) and search():
                return True
            unassign(n, removed)
        return False

    if search():
        return dict(colors)
    return None

def color_graph(nodes, edges, k, precolored=None):
    # Build adjacency sets for every node mentioned in nodes, edges, or precolored.
    adj = {}
    for n in nodes:
        adj.setdefault(n, set())
    for u, v in edges:
        if u == v:
            return None  # a self-loop can never be properly colored
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)

    coloring = {}
    if precolored:
        for n, c in precolored.items():
            if not isinstance(c, int) or not (0 <= c < k):
                return None
            adj.setdefault(n, set())
            coloring[n] = c
        # Precolored nodes must not conflict with each other.
        for n, c in coloring.items():
            for m in adj[n]:
                if m in coloring and coloring[m] == c:
                    return None

    # Initial domains: colors not already used by precolored neighbors.
    domains = {}
    for n in adj:
        if n in coloring:
            continue
        forbidden = {coloring[m] for m in adj[n] if m in coloring}
        d = set(range(k)) - forbidden
        if not d:
            return None
        domains[n] = d

    def solve(domains, coloring):
        if not domains:
            return coloring

        # Most-constrained-variable heuristic: fewest remaining colors,
        # ties broken by highest degree.
        n = min(domains, key=lambda x: (len(domains[x]), -len(adj[x])))

        for c in sorted(domains[n]):
            new_domains = {}
            ok = True
            for m, d in domains.items():
                if m == n:
                    continue
                if m in adj[n] and c in d:
                    d = d - {c}
                    if not d:
                        ok = False
                        break
                new_domains[m] = d
            if not ok:
                continue

            new_coloring = dict(coloring)
            new_coloring[n] = c
            result = solve(new_domains, new_coloring)
            if result is not None:
                return result

        return None

    return solve(domains, coloring)

