import heapq


class CycleError(Exception):
    """Raised when the dependency graph contains a cycle.

    The ``cycle`` attribute is a list of package names forming the cycle,
    with the first name repeated at the end, e.g. ['a', 'b', 'c', 'a'].
    """

    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__("dependency cycle: " + " -> ".join(self.cycle))


def _find_cycle(graph, done):
    """Return one cycle among the nodes not in ``done``."""
    visited = set()

    def visit(node, path, index):
        index[node] = len(path)
        path.append(node)
        for dep in sorted(graph[node]):
            if dep in done:
                continue
            if dep in index:
                return path[index[dep]:] + [dep]
            if dep in visited:
                continue
            found = visit(dep, path, index)
            if found:
                return found
        path.pop()
        del index[node]
        visited.add(node)
        return None

    for start in sorted(n for n in graph if n not in done):
        if start in visited:
            continue
        found = visit(start, [], {})
        if found:
            return found
    return []


def topo_order(deps):
    """Return an install order where every package follows its dependencies.

    ``deps`` maps each package to an iterable of its dependencies. Dependencies
    that do not appear as keys are treated as packages with no dependencies.
    Ties are broken alphabetically. Raises CycleError if a cycle exists.
    """
    graph = {}
    for pkg, dep_list in deps.items():
        graph.setdefault(pkg, set()).update(dep_list)
        for dep in dep_list:
            graph.setdefault(dep, set())

    remaining = {node: len(graph[node]) for node in graph}
    dependents = {node: [] for node in graph}
    for node, dep_set in graph.items():
        for dep in dep_set:
            dependents[dep].append(node)

    heap = [node for node, count in remaining.items() if count == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(order) != len(graph):
        raise CycleError(_find_cycle(graph, set(order)))

    return order

