class CycleError(Exception):
    """Raised when the dependency graph contains a cycle.

    The ``cycle`` attribute is a list of package names forming the cycle,
    with the first name repeated at the end, e.g. ``['a', 'b', 'a']``.
    """

    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__("dependency cycle: " + " -> ".join(self.cycle))


def topo_order(deps):
    """Return an install order for packages, dependencies first.

    ``deps`` maps each package to an iterable of its dependencies. Packages
    that appear only as dependencies are included in the result. Ties are
    broken alphabetically: at each step the alphabetically smallest package
    whose dependencies are all installed is emitted next.

    Raises CycleError if the dependency graph contains a cycle.
    """
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set()).update(ds)
        for d in ds:
            graph.setdefault(d, set())

    dependents = {n: set() for n in graph}
    for n, ds in graph.items():
        for d in ds:
            dependents[d].add(n)

    pending = {n: len(ds) for n, ds in graph.items()}
    heap = [n for n, count in pending.items() if count == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in dependents[n]:
            pending[m] -= 1
            if pending[m] == 0:
                heapq.heappush(heap, m)

    if len(order) != len(graph):
        remaining = set(graph) - set(order)
        # Every remaining package has at least one remaining dependency,
        # so walking dependencies must eventually revisit a package.
        current = min(remaining)
        path = []
        index = {}
        while current not in index:
            index[current] = len(path)
            path.append(current)
            current = min(d for d in graph[current] if d in remaining)
        cycle = path[index[current]:] + [current]
        raise CycleError(cycle)

    return order

