class CycleError(Exception):
    """Raised when the dependency graph contains a cycle.

    `cycle` lists the packages forming the cycle, in dependency order
    (each package depends on the next), with the first package repeated
    at the end, e.g. ['a', 'b', 'a'].
    """

    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__("dependency cycle detected: " + " -> ".join(self.cycle))


def _find_cycle(graph, stuck):
    """Return one dependency cycle among the nodes in `stuck`.

    Every stuck node has at least one dependency that is also stuck,
    so walking along stuck dependencies must eventually revisit a node.
    """
    path = []
    position = {}
    node = min(stuck)
    while node not in position:
        position[node] = len(path)
        path.append(node)
        node = min(d for d in graph[node] if d in stuck)
    return path[position[node]:] + [node]


def topo_order(deps):
    """Return an install order for packages, dependencies first.

    `deps` maps each package to an iterable of its dependencies. Packages
    that appear only as dependencies are included in the result. Ties are
    broken alphabetically, so the result is the lexicographically smallest
    valid order. Raises CycleError if the graph contains a cycle.
    """
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set()).update(ds)
        for d in ds:
            graph.setdefault(d, set())

    dependents = {n: [] for n in graph}
    remaining = {}
    for n, ds in graph.items():
        remaining[n] = len(ds)
        for d in ds:
            dependents[d].append(n)

    ready = [n for n in graph if remaining[n] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        n = heapq.heappop(ready)
        order.append(n)
        for m in dependents[n]:
            remaining[m] -= 1
            if remaining[m] == 0:
                heapq.heappush(ready, m)

    if len(order) != len(graph):
        stuck = {n for n in graph if remaining[n] > 0}
        raise CycleError(_find_cycle(graph, stuck))

    return order

