    for pkg, pkg_deps in deps.items():
        graph.setdefault(pkg, set()).update(pkg_deps)
        for d in pkg_deps:
            graph.setdefault(d, set())

    # Reverse edges: dependency -> packages that depend on it.
    dependents = {node: set() for node in graph}
    for node, node_deps in graph.items():
        for d in node_deps:
            dependents[d].add(node)

    remaining = {node: len(node_deps) for node, node_deps in graph.items()}
    ready = [node for node, count in remaining.items() if count == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(graph):
        raise CycleError(_find_cycle(graph, remaining))

    return order


def _find_cycle(graph, remaining):
    """Extract one concrete cycle from the nodes Kahn's algorithm could not place."""
    unresolved = {node for node, count in remaining.items() if count > 0}
    # Every unresolved node has at least one unresolved dependency, so
    # following dependencies from any unresolved node must eventually revisit
    # a node, which closes a cycle.
    start = min(unresolved)
    path = []
    index = {}
    node = start
    while node not in index:
        index[node] = len(path)
        path.append(node)
        node = min(d for d in graph[node] if d in unresolved)
    cycle = path[index[node]:] + [node]
    return cycle

