def column_stats(csv_text, column):
    reader = csv.reader(io.StringIO(csv_text))

    # Skip any leading blank lines so the first non-blank row is the header.
    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = row
            break

    if header is None or column not in header:
        raise KeyError(f"Column {column!r} not found in CSV header")

    index = header.index(column)

    values = []
    for row in reader:
        if index >= len(row):
            continue
        cell = row[index].strip()
        if cell == "":
            continue
        values.append(float(cell))

    count = len(values)
    if count == 0:
        return {"count": 0, "sum": 0.0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
        "count": count,
        "sum": total,
        "mean": total / count,
        "min": min(values),
        "max": max(values),
    }

