        """Insert string s at the cursor and advance the cursor past it."""
        if not s:
            return
        self._record()
        self._text = self._text[:self._cursor] + s + self._text[self._cursor:]
        self._cursor += len(s)

    def delete(self, n: int = 1) -> None:
        """Backspace: delete up to n characters before the cursor."""
        if n <= 0 or self._cursor == 0:
            return
        n = min(n, self._cursor)
        self._record()
        start = self._cursor - n
        self._text = self._text[:start] + self._text[self._cursor:]
        self._cursor = start

    def move(self, pos: int) -> None:
        """Move the cursor to pos, clamped to the valid range [0, len(text)]."""
        self._cursor = max(0, min(pos, len(self._text)))

    def undo(self) -> bool:
        """Undo the last change. Returns True if anything was undone, else False."""
        if not self._undo_stack:
            return False
        self._redo_stack.append(self._snapshot())
        self._restore(self._undo_stack.pop())
        return True

    def redo(self) -> bool:
        """Redo the last undone change. Returns True if anything was redone, else False."""
        if not self._redo_stack:
            return False
        self._undo_stack.append(self._snapshot())
        self._restore(self._redo_stack.pop())
        return True

class Editor:
    def __init__(self, text=""):
        self._text = str(text)
        self._cursor = len(self._text)
        self._undo_stack = []
        self._redo_stack = []

    @property
    def text(self):
        return self._text

    @property
    def cursor(self):
        return self._cursor

    def _snapshot(self):
        return (self._text, self._cursor)

    def _restore(self, state):
        self._text, self._cursor = state

    def _record(self, before):
        self._undo_stack.append(before)
        self._redo_stack.clear()

    def insert(self, s):
        s = str(s)
        if not s:
            return
        before = self._snapshot()
        self._text = self._text[:self._cursor] + s + self._text[self._cursor:]
        self._cursor += len(s)
        self._record(before)

    def delete(self, n=1):
        """Backspace: delete up to n characters before the cursor."""
        if n <= 0 or self._cursor == 0:
            return
        n = min(n, self._cursor)
        before = self._snapshot()
        start = self._cursor - n
        self._text = self._text[:start] + self._text[self._cursor:]
        self._cursor = start
        self._record(before)

    def move(self, pos):
        self._cursor = max(0, min(int(pos), len(self._text)))

    def undo(self):
        if not self._undo_stack:
            return False
        self._redo_stack.append(self._snapshot())
        self._restore(self._undo_stack.pop())
        return True

    def redo(self):
        if not self._redo_stack:
            return False
        self._undo_stack.append(self._snapshot())
        self._restore(self._redo_stack.pop())
        return True

import functools
import re

_SEMVER_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-((?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse(version):
    if not isinstance(version, str):
        raise ValueError(f"Invalid semantic version (not a string): {version!r}")
    match = _SEMVER_RE.fullmatch(version)
    if match is None:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    pre = match.group(4)
    prerelease = tuple(pre.split(".")) if pre else ()
    # Build metadata (group 5) is ignored for precedence.
    return major, minor, patch, prerelease


def _sign(x, y):
    if x < y:
        return -1
    if x > y:
        return 1
    return 0


def _compare_prerelease(pa, pb):
    if pa == pb:
        return 0
    # A version without pre-release fields has higher precedence.
    if not pa:
        return 1
    if not pb:
        return -1
    for x, y in zip(pa, pb):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            result = _sign(int(x), int(y))
        elif x_num:
            # Numeric identifiers have lower precedence than alphanumeric ones.
            result = -1
        elif y_num:
            result = 1
        else:
            # ASCII lexical comparison.
            result = _sign(x, y)
        if result != 0:
            return result
    # A larger set of pre-release fields has higher precedence when all
    # preceding identifiers are equal.
    return _sign(len(pa), len(pb))


def compare_versions(a, b):
    """Compare two semantic versions per SemVer 2.0.0 precedence.

    Returns -1 if a < b, 0 if a == b (precedence-wise), 1 if a > b.
    Build metadata is ignored. Raises ValueError for invalid versions.
    """
    pa = _parse(a)
    pb = _parse(b)
    for x, y in zip(pa[:3], pb[:3]):
        result = _sign(x, y)
        if result != 0:
            return result
    return _compare_prerelease(pa[3], pb[3])


def sort_versions(versions):
    """Return a new list of version strings sorted in ascending SemVer precedence.

    Raises ValueError if any version is invalid.
    """
    versions = list(versions)
    for v in versions:
        _parse(v)  # validate all inputs up front
    return sorted(versions, key=functools.cmp_to_key(compare_versions))

import re
from functools import cmp_to_key

_SEMVER_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-((?:0|[1-9][0-9]*|[0-9]*[a-zA-Z-][0-9a-zA-Z-]*)"
    r"(?:\.(?:0|[1-9][0-9]*|[0-9]*[a-zA-Z-][0-9a-zA-Z-]*))*))?"
    r"(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?"
)


def _parse(version):
    """Parse a SemVer 2.0.0 string into (major, minor, patch, prerelease_ids).

    prerelease_ids is a tuple of identifier strings, or None for a release version.
    Build metadata is validated but otherwise ignored for precedence.
    Raises ValueError for invalid input.
    """
    if not isinstance(version, str):
        raise ValueError(f"Invalid semantic version (not a string): {version!r}")
    match = _SEMVER_RE.fullmatch(version)
    if match is None:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major, minor, patch, pre, _build = match.groups()
    pre_ids = tuple(pre.split(".")) if pre is not None else None
    return int(major), int(minor), int(patch), pre_ids


def _is_numeric(identifier):
    return identifier.isdigit()


def _compare_prerelease(a, b):
    """Compare two prerelease identifier tuples (or None for release)."""
    if a is None and b is None:
        return 0
    if a is None:
        return 1  # release has higher precedence than any prerelease
    if b is None:
        return -1

    for x, y in zip(a, b):
        x_num, y_num = _is_numeric(x), _is_numeric(y)
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num:
            return -1  # numeric identifiers have lower precedence than alphanumeric
        elif y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def compare_versions(a, b):
    """Compare two semantic version strings by SemVer 2.0.0 precedence.

    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    Build metadata is ignored for precedence.
    Raises ValueError if either version is invalid.
    """
    major_a, minor_a, patch_a, pre_a = _parse(a)
    major_b, minor_b, patch_b, pre_b = _parse(b)

    for x, y in ((major_a, major_b), (minor_a, minor_b), (patch_a, patch_b)):
        if x != y:
            return -1 if x < y else 1

    return _compare_prerelease(pre_a, pre_b)


def sort_versions(versions):
    """Return a new list of version strings sorted in ascending SemVer precedence.

    Versions that compare equal (e.g. differing only in build metadata)
    keep their original relative order.
    Raises ValueError if any version is invalid.
    """
    versions = list(versions)
    for v in versions:
        _parse(v)  # validate all entries up front
    return sorted(versions, key=cmp_to_key(compare_versions))

import re
from functools import cmp_to_key

_SEMVER_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-((?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse(version):
    """Parse a SemVer 2.0.0 string into (major, minor, patch, prerelease_identifiers).

    Build metadata is validated but does not affect precedence.
    Raises ValueError for invalid versions.
    """
    if not isinstance(version, str):
        raise ValueError(f"invalid semantic version: {version!r}")
    match = _SEMVER_RE.fullmatch(version)
    if match is None:
        raise ValueError(f"invalid semantic version: {version!r}")
    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    pre = match.group(4)
    prerelease = tuple(pre.split(".")) if pre is not None else ()
    return major, minor, patch, prerelease


def _compare_identifiers(x, y):
    x_numeric = x.isdigit()
    y_numeric = y.isdigit()
    if x_numeric and y_numeric:
        xi, yi = int(x), int(y)
        return (xi > yi) - (xi < yi)
    if x_numeric:
        return -1  # numeric identifiers have lower precedence
    if y_numeric:
        return 1
    return (x > y) - (x < y)  # ASCII lexical comparison


def _compare_prerelease(a, b):
    if not a and not b:
        return 0
    if not a:
        return 1  # a normal version has higher precedence than a pre-release
    if not b:
        return -1
    for x, y in zip(a, b):
        result = _compare_identifiers(x, y)
        if result:
            return result
    return (len(a) > len(b)) - (len(a) < len(b))


def compare_versions(a, b):
    """Compare two semantic versions by SemVer 2.0.0 precedence.

    Returns -1 if a < b, 0 if a == b (in precedence), and 1 if a > b.
    Raises ValueError if either version is invalid.
    """
    a_major, a_minor, a_patch, a_pre = _parse(a)
    b_major, b_minor, b_patch, b_pre = _parse(b)

    for x, y in ((a_major, b_major), (a_minor, b_minor), (a_patch, b_patch)):
        if x != y:
            return -1 if x < y else 1

    result = _compare_prerelease(a_pre, b_pre)
    if result < 0:
        return -1
    if result > 0:
        return 1
    return 0


def sort_versions(versions):
    """Return a new list of semantic version strings sorted by SemVer 2.0.0 precedence.

    Raises ValueError if any version is invalid.
    """
    versions = list(versions)
    for version in versions:
        _parse(version)  # validate all entries up front
    return sorted(versions, key=cmp_to_key(compare_versions))

import csv
import io


def column_stats(csv_text, column):
    """Return count, sum, mean, min and max for a numeric CSV column.

    Leading blank lines before the header are ignored, and the first
    non-blank row is treated as the header. Header names are stripped of
    surrounding whitespace. Empty cells (including whitespace-only cells)
    are skipped. If no numeric values are found, sum is 0 and mean, min
    and max are None.
    """
    reader = csv.reader(io.StringIO(csv_text))

    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = [name.strip() for name in row]
            break

    if header is None or column not in header:
        raise KeyError(f"Column {column!r} not found in CSV header")

    idx = header.index(column)

    values = []
    for row in reader:
        if idx >= len(row):
            continue
        cell = row[idx].strip()
        if cell == "":
            continue
        try:
            num = int(cell)
        except ValueError:
            num = float(cell)
        values.append(num)

    count = len(values)
    if count == 0:
        return {"count": 0, "sum": 0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
        "count": count,
        "sum": total,
        "mean": total / count,
        "min": min(values),
        "max": max(values),
    }

from collections import Counter


class VendingMachine:
    ACCEPTED = (5, 10, 25)

    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._inventory = Counter(dict(coins))
        self._inserted = []

    def insert(self, coin):
        if coin not in self.ACCEPTED:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'
        price = self._prices[item]
        total = self.balance()
        if total < price:
            return 'INSUFFICIENT'
        # Coins inserted by the customer become available for making change.
        available = self._inventory + Counter(self._inserted)
        change = self._make_change(total - price, available)
        if change is None:
            return 'NO_CHANGE'
        self._inventory = available - Counter(change)
        self._inserted = []
        return change

    def cancel(self):
        returned = self._inserted
        self._inserted = []
        return returned

    def _make_change(self, amount, inventory):
        if amount == 0:
            return []
        if amount < 0 or amount % 5 != 0:
            return None
        inv25 = inventory[25]
        inv10 = inventory[10]
        inv5 = inventory[5]
        best = None
        best_count = None
        for q in range(min(inv25, amount // 25), -1, -1):
            rem1 = amount - 25 * q
            for d in range(min(inv10, rem1 // 10), -1, -1):
                rem2 = rem1 - 10 * d
                n5 = rem2 // 5
                if n5 > inv5:
                    continue
                count = q + d + n5
                if best_count is None or count < best_count:
                    best_count = count
                    best = [25] * q + [10] * d + [5] * n5
        return best

class VendingMachine:
    VALID_COINS = (5, 10, 25)

    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._inventory = {c: int(coins.get(c, 0)) for c in self.VALID_COINS}
        self._inserted = []

    def insert(self, coin):
        if coin not in self.VALID_COINS:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'
        price = self._prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'
        # Inserted coins are available for making change, along with the stock.
        available = dict(self._inventory)
        for c in self._inserted:
            available[c] += 1
        change = self._make_change(bal - price, available)
        if change is None:
            return 'NO_CHANGE'
        for c in self._inserted:
            self._inventory[c] += 1
        for c in change:
            self._inventory[c] -= 1
        self._inserted = []
        return change

    def cancel(self):
        returned = self._inserted
        self._inserted = []
        return returned

    def _make_change(self, amount, inventory):
        if amount == 0:
            return []
        items = []
        for d in sorted(self.VALID_COINS, reverse=True):
            items.extend([d] * inventory[d])
        n = len(items)
        INF = float('inf')
        dp = [[INF] * (amount + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for i, v in enumerate(items, 1):
            prev = dp[i - 1]
            cur = dp[i]
            for a in range(amount + 1):
                cur[a] = prev[a]
                if a >= v and prev[a - v] + 1 < cur[a]:
                    cur[a] = prev[a - v] + 1
        if dp[n][amount] == INF:
            return None
        result = []
        a = amount
        i = n
        while i > 0 and a > 0:
            if dp[i][a] == dp[i - 1][a]:
                i -= 1
            else:
                result.append(items[i - 1])
                a -= items[i - 1]
                i -= 1
        return sorted(result, reverse=True)
